Find an empty cell, try digits 1-9 that don't conflict with its row, column or box, and recurse. If no digit fits, undo the last choice and try the next one. Backtracking solves ordinary puzzles quickly.

```python
def solve(b):
    for i in range(81):
        if b[i] == 0:
            r, c = divmod(i, 9)
            used = {b[r*9 + k] for k in range(9)} | {b[k*9 + c] for k in range(9)}
            br, bc = r - r % 3, c - c % 3
            used |= {b[(br + x)*9 + bc + y] for x in range(3) for y in range(3)}
            for d in range(1, 10):
                if d not in used:
                    b[i] = d
                    if solve(b):
                        return True
                    b[i] = 0
            return False
    return True

puzzle = list(map(int, "530070000600195000098000060800060003400803001700020006060000280000419005000080079"))
print(solve(puzzle), puzzle[:9])  # True [5, 3, 4, 6, 7, 8, 9, 1, 2]
```

