Keep two heaps: a max-heap for the smaller half and a min-heap for the larger half, kept within one element of each other in size. The median is the top of the larger heap, or the mean of both tops. Adding a number is O(log n) and reading the median is O(1).

```python
import heapq

class MedianFinder:
    def __init__(self):
        self.small, self.large = [], []    # small is a max-heap (negated)

    def add(self, x):
        heapq.heappush(self.small, -x)
        heapq.heappush(self.large, -heapq.heappop(self.small))
        if len(self.large) > len(self.small):
            heapq.heappush(self.small, -heapq.heappop(self.large))

    def median(self):
        if len(self.small) > len(self.large):
            return -self.small[0]
        return (-self.small[0] + self.large[0]) / 2

m = MedianFinder()
for x in (5, 2, 8, 1):
    m.add(x)
print(m.median())   # 3.5
```

Compare the value with the current node: go left if smaller, right if larger, and place a new node where you hit an empty spot. The cost is O(h), where h is the tree height: O(log n) if balanced, O(n) in the worst case.

```python
class Node:
    def __init__(self, val):
        self.val, self.left, self.right = val, None, None

def insert(root, val):
    if root is None:
        return Node(val)
    if val < root.val:
        root.left = insert(root.left, val)
    elif val > root.val:
        root.right = insert(root.right, val)
    return root

def inorder(n):
    return inorder(n.left) + [n.val] + inorder(n.right) if n else []

root = None
for v in (5, 3, 8, 1, 4):
    root = insert(root, v)
print(inorder(root))   # [1, 3, 4, 5, 8]
```

Combine a hash map for O(1) lookup with a doubly linked list that orders items by recent use. On every access, move the node to the front. When over capacity, drop the node at the back. In practice, `functools.lru_cache` or `OrderedDict` already do this.

```python
class Node:
    def __init__(self, k=0, v=0):
        self.k, self.v, self.prev, self.next = k, v, None, None

class LRU:
    def __init__(self, cap):
        self.cap, self.map = cap, {}
        self.head, self.tail = Node(), Node()
        self.head.next, self.tail.prev = self.tail, self.head

    def _remove(self, n):
        n.prev.next, n.next.prev = n.next, n.prev

    def _front(self, n):
        n.next, n.prev = self.head.next, self.head
        self.head.next.prev = n
        self.head.next = n

    def get(self, k):
        if k not in self.map:
            return -1
        n = self.map[k]
        self._remove(n); self._front(n)
        return n.v

    def put(self, k, v):
        if k in self.map:
            self._remove(self.map[k])
        n = self.map[k] = Node(k, v)
        self._front(n)
        if len(self.map) > self.cap:
            old = self.tail.prev
            self._remove(old)
            del self.map[old.k]

c = LRU(2)
c.put(1, 1); c.put(2, 2); c.get(1); c.put(3, 3)
print(c.get(2), c.get(1))   # -1 1
```

Use Floyd's algorithm. First move `slow` by one and `fast` by two until they meet, which proves a cycle exists. Then reset one pointer to the head and advance both by one step; they meet exactly at the cycle's start. It is O(n) time and O(1) space.

```python
class Node:
    def __init__(self, val):
        self.val, self.next = val, None

def cycle_start(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            slow = head
            while slow is not fast:
                slow, fast = slow.next, fast.next
            return slow
    return None

nodes = [Node(i) for i in range(5)]
for a, b in zip(nodes, nodes[1:]):
    a.next = b
nodes[4].next = nodes[2]            # cycle starts at node 2
print(cycle_start(nodes[0]).val)    # 2
```

